service.method:

UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= ${POSITION}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${PHONE}
WHERE
	  HOUSE_CODE        	= ${HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, COMPANY_CODE
		, PLANT_CODE
		, USER_NAME_LOC
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL		
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
	)
	VALUES
	(
		  ${HOUSE_CODE}
		, ${USER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${COMPANY_CODE}
		, ${COMPANY_CODE}
		, ${USER_NAME_LOC}
		, ${PASSWORD}
		, ${DEPT}
		, ${POSITION}
		, ${EMAIL}				
		, 'KR'
		, 'A'
		, 'Z'
		, ${MENU_PROFILE_CODE}
		, 'A'
		, '0'
		, 'N'
		, 'N'
		, '%Y/%m/%d'
		, ${PHONE}
		, 'KO'
	)


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, DEL_FLAG			= 'Y'
WHERE
	  HOUSE_CODE        	= ${HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


UPDATE BAT_UP_IMBUPR
   SET IF_FLAG  	= #{IF_RESULT}
 WHERE INS_TIME 	= #{INS_TIME}
   AND USER_ID  	= #{USER_ID}
